"""M-CHAIR 가중 종합 설치."""
import base64, os, sys

BASE = os.path.dirname(os.path.abspath(__file__))
FILES = [
    ('docs/index.html', ''),
    ('council.py', ''),
    ('agents/meta/M-CHAIR.json', ''),
    ('agents/market/B-RATES.json', ''),
    ('agents/market/C-BUYBACK.json', ''),
    ('agents/market/F-ACTIVE.json', ''),
    ('agents/market/F-PASSIVE.json', ''),
    ('agents/market/F-SHORT.json', ''),
    ('agents/market/I-DEALER.json', ''),
    ('agents/market/I-FUND.json', ''),
    ('agents/market/I-MINOR.json', ''),
    ('agents/market/I-PENSION.json', ''),
    ('agents/market/P-ARB.json', ''),
    ('agents/market/R-LEVERAGE.json', ''),
    ('agents/market/R-RETAIL.json', ''),
]


def main():
    if not os.path.isdir(os.path.join(BASE, ".git")): print("ERROR"); return 1
    for p, b in FILES:
        full=os.path.join(BASE,p); d=os.path.dirname(full)
        if d: os.makedirs(d, exist_ok=True)
        data=base64.b64decode(b); f=open(full,"wb"); f.write(data); f.close()
    print("DONE", len(FILES)); return 0


sys.exit(main())